import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const p=JSON.parse('{"title":"Ragtime","description":"","frontmatter":{},"headers":[],"relativePath":"demos/RAGTIME.md","filePath":"demos/RAGTIME.md"}'),i={name:"demos/RAGTIME.md"};function o(s,e,h,d,l,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ragtime" tabindex="-1">Ragtime <a class="header-anchor" href="#ragtime" aria-label="Permalink to &quot;Ragtime&quot;">​</a></h1><p>The demo songs in the ragtime style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#entertainer">Whole Piece</a>: <code>entertainer.yml</code></li></ul><p><a id="entertainer"></a></p><h2 id="whole-piece-entertainer-yml" tabindex="-1">Whole Piece: <code>entertainer.yml</code> <a class="header-anchor" href="#whole-piece-entertainer-yml" aria-label="Permalink to &quot;Whole Piece: `entertainer.yml`&quot;">​</a></h2><p>All of Scott Joplin&#39;s The Entertainer, with its repeats, about four minutes, exactly as the <a href="./../IMPORTING">MIDI import</a> makes it from <code>examples/midi/entertainer.mid</code>. It&#39;s here to show how a long piece feels in the tracker, and what the import does with a piano rag. The import finds the piece&#39;s form: each scene is an eight-bar phrase, numbered and lettered by its material, S01 A, S02 B, a phrase heard again taking its letter, and the trio&#39;s scenes are in F major. Each hand is one track, <code>up a</code> the right and <code>down</code> the left, playing its chords as chords: the Chord, Tension, Inversion, Double and Omit rows say how the pianist voices each one, such as the left hand&#39;s three-finger sevenths and the right hand&#39;s octaves. <code>up b</code> holds the few notes the right hand keeps down after the others struck with them are let go.</p><p>The demo&#39;s video plays the song from the top in real time, with no live editing and no cursor moving.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/ragtime/entertainer.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/ragtime/entertainer.yml</code></a> · C major · 72 BPM · 4:13 · 19 scenes · 3 tracks · <a href="https://www.youtube.com/watch?v=zcIWxtHWwtQ" target="_blank" rel="noreferrer">▶ watch the video</a></p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">CCs</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ccs">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td></tr></tbody></table>',9)])])}const g=t(i,[["render",o]]);export{p as __pageData,g as default};
